import{A as e,C as t,D as n,O as r,S as i,b as a,t as o,w as s,x as c}from"./app-CcLSerWp.js";var l=JSON.parse(`{"path":"/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html","title":"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程","lang":"zh-CN","frontmatter":{"title":"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程","icon":"code","date":"2026-09-30T00:00:00.000Z","category":["嵌入式系统与 AUTOSAR"],"tag":["TC397","TASKING","静态库","Linker","AUTOSAR"],"isOriginal":true,"article":true,"timeline":true,"description":"沿着 .c、.o、.a 与 ELF 追踪编译、归档、链接和集成契约，厘清库的生产与使用边界。","star":true,"updated":"2026-10-15T00:00:00.000Z","head":[["meta",{"property":"og:url","content":"https://binkyle.github.io/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html"}],["meta",{"property":"og:site_name","content":"孤星旅记"}],["meta",{"property":"og:title","content":"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程"}],["meta",{"property":"og:description","content":"沿着 .c、.o、.a 与 ELF 追踪编译、归档、链接和集成契约，厘清库的生产与使用边界。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://binkyle.github.io/social-card.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:tag","content":"AUTOSAR"}],["meta",{"property":"article:tag","content":"Linker"}],["meta",{"property":"article:tag","content":"静态库"}],["meta",{"property":"article:tag","content":"TASKING"}],["meta",{"property":"article:tag","content":"TC397"}],["meta",{"property":"article:published_time","content":"2026-09-30T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-15T00:00:00.000Z"}],["link",{"rel":"canonical","href":"https://binkyle.github.io/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"WebSite\\",\\"@id\\":\\"https://binkyle.github.io/#website\\",\\"name\\":\\"孤星旅记\\",\\"alternateName\\":\\"BINKYLE\\",\\"url\\":\\"https://binkyle.github.io/\\",\\"inLanguage\\":\\"zh-CN\\",\\"author\\":{\\"@id\\":\\"https://binkyle.github.io/intro.html#person\\"}},{\\"@type\\":\\"Person\\",\\"@id\\":\\"https://binkyle.github.io/intro.html#person\\",\\"name\\":\\"Bin\\",\\"url\\":\\"https://binkyle.github.io/intro.html\\"},{\\"@type\\":\\"BlogPosting\\",\\"@id\\":\\"https://binkyle.github.io/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html#article\\",\\"url\\":\\"https://binkyle.github.io/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html\\",\\"name\\":\\"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程\\",\\"description\\":\\"沿着 .c、.o、.a 与 ELF 追踪编译、归档、链接和集成契约，厘清库的生产与使用边界。\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@id\\":\\"https://binkyle.github.io/#website\\"},\\"author\\":{\\"@id\\":\\"https://binkyle.github.io/intro.html#person\\"},\\"headline\\":\\"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程\\",\\"mainEntityOfPage\\":\\"https://binkyle.github.io/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html\\",\\"image\\":[\\"https://binkyle.github.io/social-card.png\\"],\\"datePublished\\":\\"2026-09-30T00:00:00.000Z\\",\\"dateModified\\":\\"2026-10-15T00:00:00.000Z\\"},{\\"@type\\":\\"BreadcrumbList\\",\\"@id\\":\\"https://binkyle.github.io/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html#breadcrumb\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"首页\\",\\"item\\":\\"https://binkyle.github.io/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"技术专题\\",\\"item\\":\\"https://binkyle.github.io/topics/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"AUTOSAR 与底层系统\\",\\"item\\":\\"https://binkyle.github.io/topics/autosar.html\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":4,\\"name\\":\\"从 .c 到 .a 再到 ELF：TC397 + TASKING 静态库生产与链接全流程\\",\\"item\\":\\"https://binkyle.github.io/blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.html\\"}]}]}"]]},"git":{"createdTime":1790734131000,"updatedTime":1792078969000,"contributors":[{"name":"binkyle","username":"binkyle","email":"96855579+binkyle@users.noreply.github.com","commits":4,"url":"https://github.com/binkyle"}]},"readingTime":{"minutes":9.8,"words":2939},"filePathRelative":"blog/Autosar/TC397_TASKING_Static_Library_From_Source_To_ELF.md","excerpt":"<aside class=\\"evidence-note\\" aria-labelledby=\\"evidence-summary\\">\\n<h2>从库交付到最终镜像</h2>\\n<p><strong>关键结论：</strong> Compile 产生可重定位 Object，Archive 组织库成员，Link 完成符号解析、重定位与内存放置。拿到 <code>.a</code> 不代表已经得到可运行程序，也不能用库文件大小直接推算最终 Flash 增量。</p>\\n<ul>\\n<li><strong>适用范围：</strong> 本文围绕 TC397 + TASKING 的概念与集成契约展开。实际命令参数、ABI、库变体与 LSL 约束必须对应所用工具链版本。</li>\\n<li><strong>验证方法：</strong> 沿着 Object、归档成员、未解析符号与最终 ELF/Map 逐层核对；代码与命令用于解释机制，不能代替目标工程的链接与运行验证。</li>\\n<li><strong>相关问题：</strong> 编译与放置契约明确后，可继续阅读<a href=\\"/blog/Autosar/RuntimeMeasurement/autosar-integration.html\\" target=\\"_blank\\">运行时测量接入</a>，区分“链接成功”与“运行观测有效”。</li>\\n</ul>\\n<p>内容结构复核：2026-10-15。本次编辑未执行 TASKING 或 ECU 构建。</p>\\n</aside>\\n<p>在嵌入式工程里，经常会遇到两种静态库场景：</p>\\n<ul>\\n<li><strong>作为 Producer</strong>：把自己的源码编译成 <code>.a</code>，交给其他团队或第三方集成；</li>\\n<li><strong>作为 Consumer</strong>：拿到供应商提供的 <code>.a</code>，再链接进自己的 ECU 工程。</li>\\n</ul>\\n<p>两种场景其实是同一条构建链的两端。</p>\\n<p>本文结合 <strong>TC397 + TASKING + AUTOSAR Classic</strong> 工程，完整梳理：</p>\\n<div class=\\"language-text line-numbers-mode\\" data-highlighter=\\"shiki\\" data-ext=\\"text\\" style=\\"--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10\\"><pre class=\\"shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code\\"><code class=\\"language-text\\"><span class=\\"line\\"><span>.c</span></span>\\n<span class=\\"line\\"><span> │</span></span>\\n<span class=\\"line\\"><span> │ Compile</span></span>\\n<span class=\\"line\\"><span> ▼</span></span>\\n<span class=\\"line\\"><span>.o</span></span>\\n<span class=\\"line\\"><span> │</span></span>\\n<span class=\\"line\\"><span> │ Archive</span></span>\\n<span class=\\"line\\"><span> ▼</span></span>\\n<span class=\\"line\\"><span>.a</span></span>\\n<span class=\\"line\\"><span> │</span></span>\\n<span class=\\"line\\"><span> │ Link</span></span>\\n<span class=\\"line\\"><span> ▼</span></span>\\n<span class=\\"line\\"><span>ELF</span></span>\\n<span class=\\"line\\"><span> │</span></span>\\n<span class=\\"line\\"><span> ▼</span></span>\\n<span class=\\"line\\"><span>HEX / ECU</span></span></code></pre>\\n<div class=\\"line-numbers\\" aria-hidden=\\"true\\" style=\\"counter-reset:line-number 0\\"><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div></div></div><p>重点不是某一个具体库，而是理解 <strong>Compile、Archive、Link</strong> 三个阶段分别做了什么，以及一个嵌入式静态库真正要能够被第三方使用，需要满足哪些条件。</p>\\n"}`),u={name:`TC397_TASKING_Static_Library_From_Source_To_ELF.md`},d={class:`evidence-note`,"aria-labelledby":`evidence-summary`};function f(o,l,u,f,p,m){let h=r(`RouteLink`);return n(),c(`div`,null,[a(`aside`,d,[l[6]||=a(`h2`,{id:`evidence-summary`},`从库交付到最终镜像`,-1),l[7]||=a(`p`,null,[a(`strong`,null,`关键结论：`),t(` Compile 产生可重定位 Object，Archive 组织库成员，Link 完成符号解析、重定位与内存放置。拿到 `),a(`code`,null,`.a`),t(` 不代表已经得到可运行程序，也不能用库文件大小直接推算最终 Flash 增量。`)],-1),a(`ul`,null,[l[4]||=a(`li`,null,[a(`strong`,null,`适用范围：`),t(` 本文围绕 TC397 + TASKING 的概念与集成契约展开。实际命令参数、ABI、库变体与 LSL 约束必须对应所用工具链版本。`)],-1),l[5]||=a(`li`,null,[a(`strong`,null,`验证方法：`),t(` 沿着 Object、归档成员、未解析符号与最终 ELF/Map 逐层核对；代码与命令用于解释机制，不能代替目标工程的链接与运行验证。`)],-1),a(`li`,null,[l[1]||=a(`strong`,null,`相关问题：`,-1),l[2]||=t(` 编译与放置契约明确后，可继续阅读`,-1),s(h,{to:`/blog/Autosar/RuntimeMeasurement/autosar-integration.html`},{default:e(()=>[...l[0]||=[t(`运行时测量接入`,-1)]]),_:1}),l[3]||=t(`，区分“链接成功”与“运行观测有效”。`,-1)])]),l[8]||=a(`p`,null,`内容结构复核：2026-10-15。本次编辑未执行 TASKING 或 ECU 构建。`,-1)]),l[9]||=i(`<p>在嵌入式工程里，经常会遇到两种静态库场景：</p><ul><li><strong>作为 Producer</strong>：把自己的源码编译成 <code>.a</code>，交给其他团队或第三方集成；</li><li><strong>作为 Consumer</strong>：拿到供应商提供的 <code>.a</code>，再链接进自己的 ECU 工程。</li></ul><p>两种场景其实是同一条构建链的两端。</p><p>本文结合 <strong>TC397 + TASKING + AUTOSAR Classic</strong> 工程，完整梳理：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>.c</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ Compile</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>.o</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ Archive</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>.a</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ Link</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>ELF</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>HEX / ECU</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>重点不是某一个具体库，而是理解 <strong>Compile、Archive、Link</strong> 三个阶段分别做了什么，以及一个嵌入式静态库真正要能够被第三方使用，需要满足哪些条件。</p><h2 id="_1-compile、archive、link-是三件不同的事" tabindex="-1"><a class="header-anchor" href="#_1-compile、archive、link-是三件不同的事"><span>1. Compile、Archive、Link 是三件不同的事</span></a></h2><p>很多人第一次接触静态库时，会把“编译一个库”理解成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>源码 → libxxx.a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>实际过程应该拆成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Source</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ Compiler</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Relocatable Object</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ Archiver</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Static Library</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  │ Linker</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Executable Image</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在 TASKING TriCore 工具链中，可以对应为：</p><table><thead><tr><th>阶段</th><th>工具</th><th>作用</th></tr></thead><tbody><tr><td>Compile</td><td><code>cctc</code></td><td>将 C 源文件编译成可重定位目标文件</td></tr><tr><td>Assemble</td><td><code>astc</code></td><td>将 TriCore 汇编源编译成目标文件</td></tr><tr><td>Archive</td><td><code>artc</code></td><td>将多个 <code>.o</code> 组织成静态库 <code>.a</code></td></tr><tr><td>Link</td><td><code>ltc</code></td><td>解析符号、重定位、执行 LSL 放置并生成 ELF</td></tr></tbody></table><p>因此，静态库并不是“编译完成的程序”，而是 <strong>Link 之前的一种中间交付形态</strong>。</p><hr><h2 id="_2-stage-1-从-c-到-o" tabindex="-1"><a class="header-anchor" href="#_2-stage-1-从-c-到-o"><span>2. Stage 1：从 <code>.c</code> 到 <code>.o</code></span></a></h2><p>以一个普通模块为例：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Module.c</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │ cctc</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Module.o</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对 C 源文件而言，<code>cctc</code> 作为 compiler driver，内部完成预处理、代码生成以及汇编等步骤。</p><p>可以概念化为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Module.c</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ preprocessing</span></span>
<span class="line"><span>   ├─ compilation / code generation</span></span>
<span class="line"><span>   └─ assembly</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Module.o</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>需要注意的是，<code>astc</code> 是 TriCore 汇编器，但并不是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>.c → .o → astc → 再生成一个 .o</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>对于独立的 <code>.s</code> 汇编文件，构建系统才会显式走汇编规则。</p><h3 id="编译阶段已经固定了什么" tabindex="-1"><a class="header-anchor" href="#编译阶段已经固定了什么"><span>编译阶段已经固定了什么？</span></a></h3><p>当源码变成 <code>.o</code> 时，很多关键属性其实已经确定，例如：</p><ul><li>目标 CPU / TriCore ISA；</li><li>calling convention；</li><li>数据对齐；</li><li>enum 表示方式；</li><li>浮点模型；</li><li>C/C++ ABI；</li><li>符号名称；</li><li>section 名；</li><li>部分 memory model。</li></ul><p>所以即使两个库都声称支持 TC397，也不能简单认为它们一定兼容。</p><blockquote><p><strong>CPU 相同只是第一层条件，真正决定二进制能否互相调用的是 ABI。</strong></p></blockquote><hr><h2 id="_3-一个-o-里到底有什么" tabindex="-1"><a class="header-anchor" href="#_3-一个-o-里到底有什么"><span>3. 一个 <code>.o</code> 里到底有什么？</span></a></h2><p><code>.o</code> 可以理解成：</p><blockquote><p><strong>已经生成机器代码，但还没有决定最终运行地址的可重定位模块。</strong></p></blockquote><p>一个典型 Object 中会包含：</p><h3 id="_3-1-defined-symbol" tabindex="-1"><a class="header-anchor" href="#_3-1-defined-symbol"><span>3.1 Defined Symbol</span></a></h3><p>例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>App_Init</span></span>
<span class="line"><span>App_MainFunction</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>表示这些函数由当前 Object 提供。</p><h3 id="_3-2-undefined-symbol" tabindex="-1"><a class="header-anchor" href="#_3-2-undefined-symbol"><span>3.2 Undefined Symbol</span></a></h3><p>例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Rte_Read_xxx</span></span>
<span class="line"><span>Platform_GetTime</span></span>
<span class="line"><span>memcpy</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>表示当前 Object 使用了这些符号，但定义来自其他模块或库。</p><p>Undefined Symbol 并不意味着编译失败。</p><p>它表达的是：</p><blockquote><p>“我需要这个函数，但现在还不知道它最终来自哪里，留到 Link 阶段解决。”</p></blockquote><h3 id="_3-3-relocation" tabindex="-1"><a class="header-anchor" href="#_3-3-relocation"><span>3.3 Relocation</span></a></h3><p>Object 中还会保存 relocation 信息。</p><p>因此此时：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>函数最终在哪个 Flash 地址？</span></span>
<span class="line"><span>全局变量最终在哪块 RAM？</span></span>
<span class="line"><span>外部函数最终地址是多少？</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>都还没有确定。</p><hr><h2 id="_4-section-是编译阶段和链接阶段之间的契约" tabindex="-1"><a class="header-anchor" href="#_4-section-是编译阶段和链接阶段之间的契约"><span>4. Section 是编译阶段和链接阶段之间的契约</span></a></h2><p>AUTOSAR 工程里经常会看到：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>.text.xxx</span></span>
<span class="line"><span>.rodata.xxx</span></span>
<span class="line"><span>.data.xxx</span></span>
<span class="line"><span>.bss.xxx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>或者更具体的核、本地 RAM、共享 RAM 等 section。</p><p>这些 section 名通常通过：</p><ul><li>MemMap；</li><li><code>#pragma section</code>；</li><li>compiler attribute；</li></ul><p>在 <strong>Compile 阶段</strong>写进 Object。</p><p>流程是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>函数 / 变量</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │ MemMap / pragma</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Section Name</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>.o</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>而最终：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Section</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>PFlash / LMU / DSPR / PSPR</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Final Address</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>则由 Linker + LSL 决定。</p><p>因此可以记住一句话：</p><blockquote><p><strong>Compiler 决定“属于哪个 Section”，Linker 决定“Section 最后放在哪里”。</strong></p></blockquote><hr><h2 id="_5-stage-2-从多个-o-到静态库-a" tabindex="-1"><a class="header-anchor" href="#_5-stage-2-从多个-o-到静态库-a"><span>5. Stage 2：从多个 <code>.o</code> 到静态库 <code>.a</code></span></a></h2><p>当一个模块需要以二进制形式对外交付时，可以把多个 Object 组织成一个静态库。</p><p>例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>ModuleA.o</span></span>
<span class="line"><span>ModuleB.o</span></span>
<span class="line"><span>ModuleC.o</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    │ artc</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>libProduct.a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>TASKING Archiver 的典型形式类似：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">artc</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -cr</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> libProduct.a</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -f</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> objects.rsp</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>其中 response file 用来保存较长的 Object 列表。</p><p>静态库的内部结构可以简化为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>libProduct.a</span></span>
<span class="line"><span>├── ModuleA.o</span></span>
<span class="line"><span>├── ModuleB.o</span></span>
<span class="line"><span>├── ModuleC.o</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>└── Archive Symbol Index</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>它的核心并不是“再次编译”，而是：</p><ol><li>保存多个可重定位 Object；</li><li>建立符号索引；</li><li>让 Linker 以后可以根据符号快速找到对应成员。</li></ol><p>所以 <code>.a</code> 更接近：</p><blockquote><p><strong>Object 集合 + Symbol Index</strong></p></blockquote><p>而不是一个已经完成地址分配的程序。</p><hr><h2 id="_6-为什么静态库里可以存在-undefined-symbol" tabindex="-1"><a class="header-anchor" href="#_6-为什么静态库里可以存在-undefined-symbol"><span>6. 为什么静态库里可以存在 Undefined Symbol？</span></a></h2><p>这是理解静态库最关键的一步。</p><p>假设：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>ModuleA.o</span></span>
<span class="line"><span>  Defined:</span></span>
<span class="line"><span>    Product_Init</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Undefined:</span></span>
<span class="line"><span>    Rte_Read_xxx</span></span>
<span class="line"><span>    memcpy</span></span>
<span class="line"><span>    Platform_GetTime</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>即使这些 Undefined Symbol 当前没有定义，<code>ModuleA.o</code> 仍然可以被正常放进：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>libProduct.a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>因为 <strong>Archive 阶段不负责最终符号解析</strong>。</p><p>真正的职责划分是：</p><table><thead><tr><th>行为</th><th style="text-align:right;">Compile</th><th style="text-align:right;">Archive</th><th style="text-align:right;">Link</th></tr></thead><tbody><tr><td>C → Machine Code</td><td style="text-align:right;">✅</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td></tr><tr><td>产生 Symbol</td><td style="text-align:right;">✅</td><td style="text-align:right;">保留</td><td style="text-align:right;">解析</td></tr><tr><td>产生 Relocation</td><td style="text-align:right;">✅</td><td style="text-align:right;">保留</td><td style="text-align:right;">处理</td></tr><tr><td>打包多个 Object</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td><td style="text-align:right;">❌</td></tr><tr><td>建立 Archive Index</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td><td style="text-align:right;">使用</td></tr><tr><td>决定最终地址</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td></tr><tr><td>执行 Memory Placement</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td></tr><tr><td>生成 ELF</td><td style="text-align:right;">❌</td><td style="text-align:right;">❌</td><td style="text-align:right;">✅</td></tr></tbody></table><p>因此：</p><blockquote><p><strong>生成静态库时，不需要把所有外部依赖全部解决。</strong></p></blockquote><p>真正需要保证的是：</p><blockquote><p>Consumer 最终 Link 时，所有被使用到的 Undefined Symbol 都能够找到对应定义。</p></blockquote><hr><h2 id="_7-stage-3-consumer-如何链接一个静态库" tabindex="-1"><a class="header-anchor" href="#_7-stage-3-consumer-如何链接一个静态库"><span>7. Stage 3：Consumer 如何链接一个静态库</span></a></h2><p>当另一个工程拿到：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>libProduct.a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>通常需要同时配置：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>-L&lt;library_path&gt;</span></span>
<span class="line"><span>-lProduct</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>两者职责完全不同：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>-Lxxx       → 去哪里找库</span></span>
<span class="line"><span>-lProduct   → 要链接哪个库</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>然后 Linker 开始处理：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Application Objects</span></span>
<span class="line"><span>      +</span></span>
<span class="line"><span>libProduct.a</span></span>
<span class="line"><span>      +</span></span>
<span class="line"><span>Runtime Libraries</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>      ltc</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>ELF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="linker-会把整个-a-都放进-elf-吗" tabindex="-1"><a class="header-anchor" href="#linker-会把整个-a-都放进-elf-吗"><span>Linker 会把整个 <code>.a</code> 都放进 ELF 吗？</span></a></h3><p>通常不会。</p><p>静态库最大的特点之一就是：</p><blockquote><p><strong>Linker 按需要从 Archive 中抽取 Object。</strong></p></blockquote><p>例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Application.o</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │ needs Product_Init</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Archive Symbol Index</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>找到 ModuleA.o</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>抽取 ModuleA.o</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ 又产生新的 Undefined Symbol</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>继续解析</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因此：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Archive File Size</span></span>
<span class="line"><span>≠</span></span>
<span class="line"><span>最终进入 ELF 的代码大小</span></span>
<span class="line"><span>≠</span></span>
<span class="line"><span>最终 Flash 占用</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这也是为什么一个很大的静态库，最终对 ECU ROM 的增量可能远小于库文件本身。</p><hr><h2 id="_8-linker-不只做-找函数-还要做-relocation-和-memory-placement" tabindex="-1"><a class="header-anchor" href="#_8-linker-不只做-找函数-还要做-relocation-和-memory-placement"><span>8. Linker 不只做“找函数”，还要做 Relocation 和 Memory Placement</span></a></h2><p>当需要的 Object 被抽取出来以后，Linker 还要继续完成：</p><ol><li>Symbol Resolution；</li><li>Relocation；</li><li>Section 合并；</li><li>LSL 匹配；</li><li>Memory Region 分配；</li><li>Final Address Assignment；</li><li>ELF / HEX 生成。</li></ol><p>可以把整个过程理解成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Object Section</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Linker</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>LSL select / group</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Memory Region</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Final Address</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对于 TC397 这类多核 MCU，这一步尤其重要，因为代码和数据可能需要进入：</p><ul><li>PFlash；</li><li>DSPR；</li><li>PSPR；</li><li>LMU；</li><li>cached / non-cached memory；</li><li>不同 Core 对应的专属区域。</li></ul><p>所以一个静态库即使：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>API 没问题</span></span>
<span class="line"><span>ABI 没问题</span></span>
<span class="line"><span>Symbol 也能解析</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>仍然可能因为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Section 没有正确匹配 LSL</span></span>
<span class="line"><span>Memory Region 不够</span></span>
<span class="line"><span>Startup 没有初始化对应数据</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>而无法正确运行。</p><hr><h2 id="_9-为什么嵌入式静态库不能只交付一个-a" tabindex="-1"><a class="header-anchor" href="#_9-为什么嵌入式静态库不能只交付一个-a"><span>9. 为什么嵌入式静态库不能只交付一个 <code>.a</code></span></a></h2><p>假设我们作为 Producer，要把：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>libProduct.a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>交给第三方。</p><p>真正完整的交付至少应该考虑下面几类信息。</p><h3 id="_9-1-public-header" tabindex="-1"><a class="header-anchor" href="#_9-1-public-header"><span>9.1 Public Header</span></a></h3><p>第三方需要知道：</p><ul><li>API 函数；</li><li>struct / enum；</li><li>callback；</li><li>version；</li><li>public typedef。</li></ul><h3 id="_9-2-abi-要求" tabindex="-1"><a class="header-anchor" href="#_9-2-abi-要求"><span>9.2 ABI 要求</span></a></h3><p>例如：</p><ul><li>Target CPU / ISA；</li><li>Compiler / compatible ABI；</li><li>alignment；</li><li>enum model；</li><li>floating-point model；</li><li>C/C++ ABI。</li></ul><h3 id="_9-3-link-dependencies" tabindex="-1"><a class="header-anchor" href="#_9-3-link-dependencies"><span>9.3 Link Dependencies</span></a></h3><p>例如：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>libProduct.a</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>runtime library</span></span>
<span class="line"><span>platform library</span></span>
<span class="line"><span>AUTOSAR BSW / RTE symbols</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果库依赖其他 library，需要明确告诉 Consumer。</p><h3 id="_9-4-memory-lsl-contract" tabindex="-1"><a class="header-anchor" href="#_9-4-memory-lsl-contract"><span>9.4 Memory / LSL Contract</span></a></h3><p>如果库定义了特殊 section：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>.data.xxx</span></span>
<span class="line"><span>.bss.xxx</span></span>
<span class="line"><span>.text.xxx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>第三方可能还需要同步：</p><ul><li>LSL select；</li><li>memory region；</li><li>alignment；</li><li>cached / non-cached 属性。</li></ul><h3 id="_9-5-startup-runtime-contract" tabindex="-1"><a class="header-anchor" href="#_9-5-startup-runtime-contract"><span>9.5 Startup / Runtime Contract</span></a></h3><p>还可能涉及：</p><ul><li><code>.data</code> copy；</li><li><code>.bss</code> clear；</li><li>Init API；</li><li>Task / Core；</li><li>Heap / Stack；</li><li>callback；</li><li>RTE / MCAL / OS dependency。</li></ul><p>因此：</p><blockquote><p><strong>真正交付的不是一个 <code>.a</code> 文件，而是一套二进制接口契约。</strong></p></blockquote><hr><h2 id="_10-producer-和-consumer-是同一条链的两端" tabindex="-1"><a class="header-anchor" href="#_10-producer-和-consumer-是同一条链的两端"><span>10. Producer 和 Consumer 是同一条链的两端</span></a></h2><p>可以用两个匿名化场景理解。</p><h3 id="producer-把自己的模块做成库" tabindex="-1"><a class="header-anchor" href="#producer-把自己的模块做成库"><span>Producer：把自己的模块做成库</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Product Source</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      │ cctc</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Objects</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      │ artc</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>libProduct.a</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>交付第三方</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="consumer-接入供应商提供的库" tabindex="-1"><a class="header-anchor" href="#consumer-接入供应商提供的库"><span>Consumer：接入供应商提供的库</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Supplier</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>libVendor.a + headers</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>当前工程</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ include path</span></span>
<span class="line"><span>   ├─ library path</span></span>
<span class="line"><span>   ├─ -lVendor</span></span>
<span class="line"><span>   ├─ runtime dependencies</span></span>
<span class="line"><span>   └─ LSL / startup</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>ltc</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>ELF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这两种场景实际上遵循同一个规则：</p><blockquote><p>Producer 在 Compile / Archive 阶段固定二进制边界，Consumer 在 Link 阶段完成最终解析和部署。</p></blockquote><hr><h2 id="_11-最容易混淆的几个概念" tabindex="-1"><a class="header-anchor" href="#_11-最容易混淆的几个概念"><span>11. 最容易混淆的几个概念</span></a></h2><h3 id="_11-1-o-不是最终程序" tabindex="-1"><a class="header-anchor" href="#_11-1-o-不是最终程序"><span>11.1 <code>.o</code> 不是最终程序</span></a></h3><p>它已经包含机器码，但仍然可能有：</p><ul><li>Undefined Symbol；</li><li>Relocation；</li><li>未确定的最终地址。</li></ul><h3 id="_11-2-a-不是-已经链接好的模块" tabindex="-1"><a class="header-anchor" href="#_11-2-a-不是-已经链接好的模块"><span>11.2 <code>.a</code> 不是“已经链接好的模块”</span></a></h3><p>它本质上是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>Object 集合 + Symbol Index</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>最终 Link 仍然不可缺少。</p><h3 id="_11-3-同一个-mcu-不代表库一定兼容" tabindex="-1"><a class="header-anchor" href="#_11-3-同一个-mcu-不代表库一定兼容"><span>11.3 同一个 MCU 不代表库一定兼容</span></a></h3><p>除了 CPU，还必须看：</p><ul><li>ABI；</li><li>compiler options；</li><li>data model；</li><li>floating-point model；</li><li>alignment；</li><li>runtime。</li></ul><h3 id="_11-4-能找到库不代表集成完成" tabindex="-1"><a class="header-anchor" href="#_11-4-能找到库不代表集成完成"><span>11.4 能找到库不代表集成完成</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>找到 .a</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>API 可编译</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Symbol 可解析</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Section 可放置</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Startup 正确</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Runtime 正确</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>任何一层出问题，都可能表现成完全不同的故障。</p><h3 id="_11-5-库文件大小不等于-rom-ram-占用" tabindex="-1"><a class="header-anchor" href="#_11-5-库文件大小不等于-rom-ram-占用"><span>11.5 库文件大小不等于 ROM/RAM 占用</span></a></h3><p><code>.a</code> 里还可能包含：</p><ul><li>Debug Information；</li><li>Symbol Table；</li><li>String Table；</li><li>Relocation；</li><li>未被最终抽取的 Object。</li></ul><p>实际资源占用应该看：</p><blockquote><p><strong>最终 ELF / Map 中真正进入镜像的 ALLOC Section。</strong></p></blockquote><hr><h2 id="_12-总结" tabindex="-1"><a class="header-anchor" href="#_12-总结"><span>12. 总结</span></a></h2><p>一个 TC397 静态库从源码到最终 ECU 镜像，可以抽象成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>.c</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ Compile</span></span>
<span class="line"><span> │ 固定 ISA / ABI / Symbol / Section</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>.o</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ Archive</span></span>
<span class="line"><span> │ 组织 Object + 建立 Symbol Index</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>.a</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ Link</span></span>
<span class="line"><span> │ 抽取成员 + Symbol Resolution + Relocation</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>LSL</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> │ Memory Placement</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>ELF</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>HEX / ECU Runtime</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>真正需要记住的是三点：</p><blockquote><p><strong>第一，<code>.o</code> 可以保留 Undefined Symbol，因为最终解析发生在 Link 阶段。</strong></p></blockquote><blockquote><p><strong>第二，<code>.a</code> 本质上是可重定位 Object 的归档，而不是已经完成链接的程序。</strong></p></blockquote><blockquote><p><strong>第三，嵌入式静态库是否真正可用，不只取决于 API，还取决于 ABI、Runtime、Section、LSL、Startup 和最终执行环境。</strong></p></blockquote><p>理解了 <strong>Compile → Archive → Link</strong> 的职责边界之后，很多工程问题都会变得更直观：</p><ul><li>为什么同一个 TC397 的库仍可能不能直接使用；</li><li>为什么 <code>-lxxx</code> 找到了库却还会报 Undefined Symbol；</li><li>为什么库文件很大但 Flash 增量并不大；</li><li>为什么接入一个静态库还可能需要修改 LSL；</li><li>为什么一个真正可交付的静态库远不止一个 <code>.a</code> 文件。</li></ul><h2 id="公开资料与复核范围" tabindex="-1"><a class="header-anchor" href="#公开资料与复核范围"><span>公开资料与复核范围</span></a></h2><ul><li><a href="https://www.tasking.com/documentation/tricore/getting_started/project_create.html" target="_blank" rel="noopener noreferrer">TASKING：创建 TriCore 工程</a>：核对 Library 工程类型、目标处理器、Startup 与 LSL 的配置入口。</li><li><a href="https://www.tasking.com/documentation/tricore/getting_started/project_options.html" target="_blank" rel="noopener noreferrer">TASKING：设置工程选项</a>：核对 Compiler、Assembler、Linker 与 Archiver 的选项分工。</li><li><a href="https://www.tasking.com/support/tricore/" target="_blank" rel="noopener noreferrer">TASKING TriCore 官方支持与文档入口</a>：查找与实际安装版本一致的 User Guide。本文未把入口中的最新版本当作已验证的项目版本。</li></ul><p>以上公开页面查阅于 2026-10-15；本文的构建链解释与示意命令不构成任何特定工具链补丁版本的兼容性认证。</p>`,194)])}var p=o(u,[[`render`,f]]);export{l as _pageData,p as default};